class Solution {

    public List<Integer> topView(TreeNode root) {
        TreeMap<Integer, int[]> map = new TreeMap<>(); // hd -> {depth, val}
        dfs(root, 0, 0, map);
        List<Integer> res = new ArrayList<>();
        for (int[] e : map.values()) res.add(e[1]);
        return res;
    }

    private void dfs(
        TreeNode node,
        int hd,
        int depth,
        TreeMap<Integer, int[]> map
    ) {
        if (node == null) return;
        int[] cur = map.get(hd);
        if (cur == null || depth < cur[0]) map.put(hd, new int[] {
            depth,
            node.val,
        }); // shallower wins

        dfs(node.left, hd - 1, depth + 1, map);
        dfs(node.right, hd + 1, depth + 1, map);
    }
}

