class Solution {

    public List<Integer> topView(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        if (root == null) return res;
        Map<Integer, Integer> first = new HashMap<>(); // hd -> topmost value
        Queue<TreeNode> nodes = new ArrayDeque<>();
        Queue<Integer> hds = new ArrayDeque<>();
        nodes.add(root);
        hds.add(0);
        int min = 0,
            max = 0;
        while (!nodes.isEmpty()) {
            TreeNode node = nodes.poll();
            int hd = hds.poll();
            first.putIfAbsent(hd, node.val); // first seen in BFS = topmost
            min = Math.min(min, hd);
            max = Math.max(max, hd);
            if (node.left != null) {
                nodes.add(node.left);
                hds.add(hd - 1);
            }
            if (node.right != null) {
                nodes.add(node.right);
                hds.add(hd + 1);
            }
        }
        for (int hd = min; hd <= max; hd++) res.add(first.get(hd));
        return res;
    }
}

