        max = 0;
    for (let i = 0; i < queue.length; i++) {
        // index pointer avoids O(n) shift()
        const [node, hd] = queue[i];
        if (!first.has(hd)) first.set(hd, node.val); // first seen in BFS = topmost
        min = Math.min(min, hd);
        max = Math.max(max, hd);
        if (node.left) queue.push([node.left, hd - 1]);
        if (node.right) queue.push([node.right, hd + 1]);
    }
    const res = [];
    for (let hd = min; hd <= max; hd++) res.push(first.get(hd));
    return res;
}

