class Solution {

    private Map<TreeNode, Integer> depth = new HashMap<>();

    public List<Integer> distanceK(
        TreeNode root,
        TreeNode target,
        int k
    ) {
        fillDepth(root, 0);
        List<Integer> res = new ArrayList<>();
        for (TreeNode node : depth.keySet()) {
            TreeNode lca = lca(root, node, target);
            int dist =
                depth.get(node) +
                depth.get(target) -
                2 * depth.get(lca);
            if (dist == k) res.add(node.val);
        }
        return res;
    }

    private void fillDepth(TreeNode node, int d) {
        if (node == null) return;
        depth.put(node, d);
        fillDepth(node.left, d + 1);
        fillDepth(node.right, d + 1);
    }

    private TreeNode lca(TreeNode root, TreeNode p, TreeNode q) {
        if (root == null || root == p || root == q) return root;
        TreeNode l = lca(root.left, p, q),
            r = lca(root.right, p, q);
        if (l != null && r != null) return root;
        return l != null ? l : r;
    }
}

