        const l = lca(node.left, p, q),
            r = lca(node.right, p, q);
        if (l && r) return node;
        return l || r;
    };
    fill(root, 0);
    const res = [];
    for (const [node, d] of depth) {
        const a = lca(root, node, target);
        if (d + depth.get(target) - 2 * depth.get(a) === k)
            res.push(node.val);
    }
    return res;
};

