class Solution {

    public List<Integer> distanceK(
        TreeNode root,
        TreeNode target,
        int k
    ) {
        Map<TreeNode, TreeNode> parent = new HashMap<>();
        buildParents(root, null, parent);

        Queue<TreeNode> q = new ArrayDeque<>();
        Set<TreeNode> visited = new HashSet<>();
        q.add(target);
        visited.add(target);
        int dist = 0;

        while (!q.isEmpty() && dist < k) {
            int size = q.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = q.poll();
                for (TreeNode nb : new TreeNode[] {
                    node.left,
                    node.right,
                    parent.get(node),
                }) {
                    if (nb != null && visited.add(nb)) q.add(nb); // add() returns false if seen
                }
            }
            dist++;
        }
        List<Integer> res = new ArrayList<>();
        for (TreeNode node : q) res.add(node.val);
        return res;
    }

    private void buildParents(
        TreeNode node,
        TreeNode par,
        Map<TreeNode, TreeNode> parent
    ) {
        if (node == null) return;
        parent.put(node, par);
        buildParents(node.left, node, parent);
        buildParents(node.right, node, parent);
    }
}

