        parent.set(node, par);
        build(node.left, node);
        build(node.right, node);
    };
    build(root, null);

    let level = [target];
    const visited = new Set([target]);
    for (let dist = 0; dist < k && level.length; dist++) {
        const next = [];
        for (const node of level) {
            for (const nb of [
                node.left,
                node.right,
                parent.get(node),
            ]) {
                if (nb && !visited.has(nb)) {
                    visited.add(nb);
                    next.push(nb);
                }
            }
        }
        level = next;
    }
    return level.map((n) => n.val);
};

