class Solution {

    public int amountOfTime(TreeNode root, int start) {
        Map<TreeNode, TreeNode> parent = new HashMap<>();
        List<TreeNode> all = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        parent.put(root, null);
        TreeNode src = null;
        while (!stack.isEmpty()) {
            // collect nodes + parents
            TreeNode n = stack.pop();
            all.add(n);
            if (n.val == start) src = n;
            if (n.left != null) {
                parent.put(n.left, n);
                stack.push(n.left);
            }
            if (n.right != null) {
                parent.put(n.right, n);
                stack.push(n.right);
            }
        }
        Set<TreeNode> burnt = new HashSet<>();

        burnt.add(src);
        int minutes = 0;
        while (burnt.size() < all.size()) {
            List<TreeNode> newly = new ArrayList<>();
            for (TreeNode n : all) {
                if (burnt.contains(n)) continue;
                TreeNode p = parent.get(n);
                if (
                    (n.left != null && burnt.contains(n.left)) ||
                    (n.right != null && burnt.contains(n.right)) ||
                    (p != null && burnt.contains(p))
                ) newly.add(n);
            }
            burnt.addAll(newly); // apply after the scan = one minute
            minutes++;
        }
        return minutes;
    }
}

