class Solution {

    public int amountOfTime(TreeNode root, int start) {
        Map<TreeNode, TreeNode> parent = new HashMap<>();
        Queue<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        TreeNode src = null;
        while (!q.isEmpty()) {
            // BFS to record parents
            TreeNode n = q.poll();
            if (n.val == start) src = n;
            if (n.left != null) {
                parent.put(n.left, n);
                q.add(n.left);
            }
            if (n.right != null) {
                parent.put(n.right, n);
                q.add(n.right);
            }
        }

        Set<TreeNode> visited = new HashSet<>();
        q.add(src);
        visited.add(src);
        int minutes = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            boolean spread = false;
            for (int i = 0; i < size; i++) {
                TreeNode n = q.poll();
                for (TreeNode nb : new TreeNode[] {
                    n.left,
                    n.right,
                    parent.get(n),
                }) {
                    if (nb != null && visited.add(nb)) {
                        q.add(nb);
                        spread = true;
                    }
                }
            }
            if (spread) minutes++; // only count minutes that burn something
        }
        return minutes;
    }
}

