class Solution {

    private int minCol = 0,
        maxCol = 0;

    public List<List<Integer>> verticalTraversal(TreeNode root) {
        findRange(root, 0);
        List<List<Integer>> res = new ArrayList<>();
        for (int c = minCol; c <= maxCol; c++) {
            List<int[]> cells = new ArrayList<>(); // {row, val}
            collect(root, 0, 0, c, cells);
            cells.sort((a, b) ->
                a[0] != b[0]
                    ? Integer.compare(a[0], b[0])
                    : Integer.compare(a[1], b[1])
            );
            List<Integer> col = new ArrayList<>();
            for (int[] cell : cells) col.add(cell[1]);
            res.add(col);
        }
        return res;
    }

    private void findRange(TreeNode node, int col) {
        if (node == null) return;
        minCol = Math.min(minCol, col);

        maxCol = Math.max(maxCol, col);
        findRange(node.left, col - 1);
        findRange(node.right, col + 1);
    }

    private void collect(
        TreeNode node,
        int row,
        int col,
        int target,
        List<int[]> cells
    ) {
        if (node == null) return;
        if (col == target) cells.add(new int[] { row, node.val });
        collect(node.left, row + 1, col - 1, target, cells);
        collect(node.right, row + 1, col + 1, target, cells);
    }
}

