class Solution {

    public TreeNode lowestCommonAncestor(
        TreeNode root,
        TreeNode p,
        TreeNode q
    ) {
        List<TreeNode> pathP = new ArrayList<>(),
            pathQ = new ArrayList<>();
        findPath(root, p, pathP);
        findPath(root, q, pathQ);
        TreeNode lca = null;
        for (int i = 0; i < Math.min(pathP.size(), pathQ.size()); i++) {
            if (pathP.get(i) != pathQ.get(i)) break; // paths diverge here
            lca = pathP.get(i);
        }
        return lca;
    }

    private boolean findPath(
        TreeNode node,
        TreeNode target,
        List<TreeNode> path
    ) {
        if (node == null) return false;
        path.add(node);
        if (node == target) return true;

        if (
            findPath(node.left, target, path) ||
            findPath(node.right, target, path)
        ) return true;
        path.remove(path.size() - 1); // not on this branch
        return false;
    }
}

