class Solution {

    public List<Integer> boundaryOfBinaryTree(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        if (root == null) return res;
        List<TreeNode> order = new ArrayList<>();
        order.add(root);
        for (
            TreeNode n = root.left;
            n != null;
            n = n.left != null ? n.left : n.right
        ) order.add(n);
        collectLeaves(root, order);
        List<TreeNode> right = new ArrayList<>();
        for (
            TreeNode n = root.right;
            n != null;
            n = n.right != null ? n.right : n.left
        ) right.add(n);
        Collections.reverse(right);
        order.addAll(right);

        Set<TreeNode> seen = new HashSet<>(); // identity-based: TreeNode has no equals()

        for (TreeNode n : order) if (seen.add(n)) res.add(n.val);
        return res;
    }

    private void collectLeaves(TreeNode n, List<TreeNode> out) {
        if (n == null) return;
        if (n.left == null && n.right == null) {
            out.add(n);
            return;
        }
        collectLeaves(n.left, out);
        collectLeaves(n.right, out);
    }
}

