class Solution {

    public boolean findTarget(TreeNode root, int k) {
        if (root == null) return false;
        BSTIterator asc = new BSTIterator(root, false);
        BSTIterator desc = new BSTIterator(root, true);
        int i = asc.next(),
            j = desc.next();
        while (i < j) {
            // values are distinct, so i < j means different nodes
            long sum = (long) i + j; // long avoids overflow for extreme values
            if (sum == k) return true;
            if (sum < k) i = asc.next();
            else j = desc.next();
        }
        return false;
    }

    static class BSTIterator {

        private final Deque<TreeNode> stack = new ArrayDeque<>();
        private final boolean reverse;

        BSTIterator(TreeNode root, boolean reverse) {
            this.reverse = reverse;
            pushSpine(root);
        }

        int next() {
            TreeNode n = stack.pop();
            pushSpine(reverse ? n.left : n.right); // next smaller / next larger subtree
            return n.val;
        }

        private void pushSpine(TreeNode n) {
            while (n != null) {
                stack.push(n);
                n = reverse ? n.right : n.left;
            }
        }
    }
}

