        if (root == null) return 0;
        if (isBST(root, Long.MIN_VALUE, Long.MAX_VALUE)) return count(
            root
        ); // whole subtree is a BST
        return Math.max(
            largestBSTSubtree(root.left),
            largestBSTSubtree(root.right)
        );
