    const isBST = (n, low, high) => {
        if (!n) return true;
        if (n.val <= low || n.val >= high) return false;
        return isBST(n.left, low, n.val) && isBST(n.right, n.val, high);
    };
    const count = (n) => (n ? 1 + count(n.left) + count(n.right) : 0);
    if (!root) return 0;
    if (isBST(root, -Infinity, Infinity)) return count(root); // whole subtree is a BST
    return Math.max(
        largestBSTSubtree(root.left),
        largestBSTSubtree(root.right),
    );
};

