class Solution {

    public int largestBSTSubtree(TreeNode root) {
        return (int) post(root)[2];
    }

    // returns {min, max, size}; size is the best BST size if this subtree is not a BST
    private long[] post(TreeNode node) {
        if (node == null) return new long[] {
            Long.MAX_VALUE,
            Long.MIN_VALUE,
            0,
        };
        long[] l = post(node.left),
            r = post(node.right);
        if (l[1] < node.val && node.val < r[0]) {
            // valid BST rooted here
            return new long[] {
                Math.min(l[0], node.val),
                Math.max(r[1], node.val),
                l[2] + r[2] + 1,
            };
        }
        return new long[] {
            Long.MIN_VALUE,
            Long.MAX_VALUE,
            Math.max(l[2], r[2]),
        }; // poison ancestors
    }
}

