var largestBSTSubtree = function (root) {
    // returns [min, max, size]; size is the best BST size if this subtree is not a BST
    const post = (node) => {
        if (!node) return [Infinity, -Infinity, 0];
        const l = post(node.left),
            r = post(node.right);
        if (l[1] < node.val && node.val < r[0]) {
            // valid BST rooted here
            return [
                Math.min(l[0], node.val),
                Math.max(r[1], node.val),
                l[2] + r[2] + 1,
            ];
        }
        return [-Infinity, Infinity, Math.max(l[2], r[2])]; // poison ancestors
    };
    return post(root)[2];
};
